package com.financecoach.controller;
import com.financecoach.dto.ReportDto;import com.financecoach.security.UserPrincipal;import com.financecoach.service.ReportService;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reports") public class ReportController {private final ReportService service;public ReportController(ReportService service){this.service=service;}@GetMapping("/monthly")public ResponseEntity<ReportDto> monthly(@AuthenticationPrincipal UserPrincipal p,@RequestParam(required=false)Integer month,@RequestParam(required=false)Integer year){return ResponseEntity.ok(service.monthly(p.getId(),month,year));}}
